data = json.loads(P.read_text())
seen = set()
for g in data['services']:
    if g['id'] in G:
        g.update(G[g['id']])
        seen.add(g['id'])
missing = [g['id'] for g in data['services'] if g['confidence'] == 'high' and g['id'] not in seen]
P.write_text(json.dumps(data, indent=1, ensure_ascii=False) + '\n')
print('updated', len(seen), 'missing', missing)
for k, v in G.items():
    n = len(v['answer'].split())
    if n > 60 or n < 12:
        print('answer length', k, n)
